class Solution:
    def invalidTransactions(self, transactions: List[str]) -> List[str]:
        n = len(transactions)
        parsed = [t.split(',') for t in transactions]
        bad = [False] * n
        for i in range(n):
            if int(parsed[i][2]) > 1000:
                bad[i] = True
            for j in range(i + 1, n):
                if parsed[i][0] == parsed[j][0] and parsed[i][3] != parsed[j][3] and abs(int(parsed[i][1]) - int(parsed[j][1])) <= 60:
                    bad[i] = bad[j] = True
        return [transactions[i] for i in range(n) if bad[i]]

