class Solution {
    public List<String> invalidTransactions(String[] transactions) {
        int n = transactions.length;
        String[][] p = new String[n][];
        boolean[] bad = new boolean[n];
        for (int i = 0; i < n; i++) {
            p[i] = transactions[i].split(",");
            if (Integer.parseInt(p[i][2]) > 1000) bad[i] = true;
        }
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (p[i][0].equals(p[j][0]) && !p[i][3].equals(p[j][3])
                        && Math.abs(Integer.parseInt(p[i][1]) - Integer.parseInt(p[j][1])) <= 60)
                    bad[i] = bad[j] = true;
        List<String> res = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (bad[i]) res.add(transactions[i]);
        return res;
    }
}

