        bad = set()
        for i, t in enumerate(transactions):
            name, time, amt, city = t.split(',')
            groups[name].append((i, int(time), city))
            if int(amt) > 1000:
                bad.add(i)
        for items in groups.values():
            m = len(items)
            for a in range(m):
                for b in range(a + 1, m):
                    ia, ta, ca = items[a]
                    ib, tb, cb = items[b]
                    if ca != cb and abs(ta - tb) <= 60:
                        bad.add(ia)
                        bad.add(ib)
        return [transactions[i] for i in range(len(transactions)) if i in bad]

