class Solution {
public:
    vector<string> invalidTransactions(vector<string>& transactions) {
        unordered_map<string, vector<array<int,3>>> groups;
        unordered_set<int> bad;
        for (int i = 0; i < (int)transactions.size(); i++) {
            stringstream ss(transactions[i]);
            string name, time, amt, city;
            getline(ss, name, ','); getline(ss, time, ',');
            getline(ss, amt, ','); getline(ss, city, ',');
            groups[name].push_back({i, stoi(time), 0});
            groups[name].back()[2] = (int)groups[name].size() - 1;
            if (stoi(amt) > 1000) bad.insert(i);
        }
        for (auto& [name, items] : groups) {
            int m = items.size();
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    auto& x = items[a]; auto& y = items[b];
                    if (transactions[x[0]].substr(transactions[x[0]].find_last_of(',')+1)
                        != transactions[y[0]].substr(transactions[y[0]].find_last_of(',')+1)
                        && abs(x[1] - y[1]) <= 60) {
                        bad.insert(x[0]); bad.insert(y[0]);
                    }
                }
        }
        vector<string> res;
        for (int i = 0; i < (int)transactions.size(); i++)
            if (bad.count(i)) res.push_back(transactions[i]);
        return res;
    }
};

