class Solution {
    public List<String> invalidTransactions(String[] transactions) {
        Map<String, List<int[]>> groups = new HashMap<>();
        Set<Integer> bad = new HashSet<>();
        String[][] parts = new String[transactions.length][];
        for (int i = 0; i < transactions.length; i++) {
            parts[i] = transactions[i].split(",");
            groups.computeIfAbsent(parts[i][0], k -> new ArrayList<>()).add(new int[]{i, Integer.parseInt(parts[i][1])});
            if (Integer.parseInt(parts[i][2]) > 1000) bad.add(i);
        }
        for (List<int[]> items : groups.values()) {
            int m = items.size();
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    int[] x = items.get(a), y = items.get(b);
                    if (!parts[x[0]][3].equals(parts[y[0]][3]) && Math.abs(x[1] - y[1]) <= 60) {
                        bad.add(x[0]); bad.add(y[0]);
                    }
                }
        }
        List<String> res = new ArrayList<>();
        for (int i = 0; i < transactions.length; i++)
            if (bad.contains(i)) res.add(transactions[i]);
        return res;
    }
}

