    const parts = transactions.map(t => t.split(','));
    parts.forEach((p, i) => {
        if (!groups.has(p[0])) groups.set(p[0], []);
        groups.get(p[0]).push([i, +p[1]]);
        if (+p[2] > 1000) bad.add(i);
    });
    for (const items of groups.values()) {
        for (let a = 0; a < items.length; a++)
            for (let b = a + 1; b < items.length; b++) {
                const [ia, ta] = items[a], [ib, tb] = items[b];
                if (parts[ia][3] !== parts[ib][3] && Math.abs(ta - tb) <= 60) {
                    bad.add(ia); bad.add(ib);
                }
            }
    }
    return transactions.filter((_, i) => bad.has(i));
};
